   6 │ using UnityEngine;
   7 │ using System.Collections;
   8 │ public class {name} : MonoBehaviour
   9 │ {{
  10 │     public GameObject prefabToSpawn;
  11 │     public float spawnInterval = 2f;
  12 │     public int maxSpawned = 10;
  13 │     public Transform[] spawnPoints;
  14 │     private int currentCount = 0;
  15 │     void Start() {{ StartCoroutine(SpawnLoop()); }}
  16 │     IEnumerator SpawnLoop()
  17 │     {{
  18 │         while (true)
  19 │         {{
  20 │             yield return new WaitForSeconds(spawnInterval);
  21 │             SpawnEnemy();
  22 │         }}
  23 │     }}
  24 │     public GameObject SpawnEnemy()
  25 │     {{
  26 │         if (currentCount >= maxSpawned || prefabToSpawn == null || spawnPoints == null || spawnPoints.Length == 0)
  27 │             return null;
  28 │         Transform sp = spawnPoints[Random.Range(0, spawnPoints.Length)];
  29 │         GameObject enemy = Instantiate(prefabToSpawn, sp.position, Quaternion.identity);
  30 │         currentCount++;
  31 │         return enemy;
  32 │     }}
  33 │     public void OnObjectDestroyed() {{ currentCount = Mathf.Max(0, currentCount - 1); }}
  34 │ }}""",
