  36 │ using UnityEngine;
  37 │ public class {name} : MonoBehaviour
  38 │ {{
  39 │     public static {name} Instance;
  40 │     public int score = 0;
  41 │     public int wave = 1;
  42 │     public bool isGameOver = false;
  43 │     public GameObject enemyPrefab;
  44 │     public Transform[] spawnPoints;
  45 │     private int enemiesAlive = 0;
  46 │     void Awake() {{ Instance = this; }}
  47 │     void Start() {{ if (spawnPoints.Length > 0 && enemyPrefab != null) SpawnWave(); }}
  48 │     public void SpawnWave()
  49 │     {{
  50 │         int count = wave * 2;
  51 │         enemiesAlive = count;
  52 │         for (int i = 0; i < count; i++)
  53 │             Instantiate(enemyPrefab, spawnPoints[i % spawnPoints.Length].position, Quaternion.identity);
  54 │         Debug.Log("Wave " + wave + " | Enemies: " + count);
  55 │     }}
  56 │     public void OnEnemyKilled()
  57 │     {{
  58 │         score += 10 * wave;
  59 │         enemiesAlive--;
  60 │         if (enemiesAlive <= 0) {{ wave++; Invoke(nameof(SpawnWave), 3f); }}
  61 │     }}
  62 │     public void GameOver()
  63 │     {{
  64 │         isGameOver = true;
  65 │         Time.timeScale = 0f;
  66 │         Debug.Log("Game Over! Score: " + score);
  67 │     }}
  68 │ }}""",
